159	function observe(state: TurnFailures, error: unknown): void {
160	  state.evidence = mergeHarnessFailure(state.evidence, harnessFailureEvidence(error));
161	}
162	
163	function requireAcceptanceRecording(state: TurnFailures): void {
164	  if (state.acceptanceFailure) throw state.acceptanceFailure.error;
165	}
