167	/** Recording is secondary: it cannot replace the selected evidence or authorize another call. */
168	async function recordSubmission(
169	  ctx: NodeContext<'inference'>,
170	  pending: PendingTurn,
171	  state: TurnFailures,
172	  value: Parameters<typeof submission>[2],
173	  marker?: Parameters<typeof submission>[3],
174	): Promise<void> {
175	  try {
176	    await submission(ctx, pending, value, marker);
177	  } catch (error) {
178	    recordingFault(ctx, pending, state, 'harness.submission', error);
179	    if (marker) state.acceptanceFailure = { error };
180	  }
181	}
