274	/** An explicitly returned native candidate stays authoritative, including undefined or null. */
275	function outputCandidate(result: HarnessResult): unknown {
276	  return Object.hasOwn(result, 'structured') ? result.structured : jsonOrText(result.finalText);
277	}
278	
279	function noteFor(item: HarnessItem): string | undefined {
280	  switch (item.type) {
281	    case 'command':
282	      return `Ran: ${item.summary}`;
283	    case 'file-change':
284	      return `Changed: ${item.summary}`;
285	    case 'tool-call':
286	      return `Tool: ${item.summary}`;
287	    default:
288	      return undefined;
289	  }
290	}
