292	export const inferenceHandler: NodeHandler<'inference'> = {
293	  kind: 'inference',
294	  async execute(ctx) {
295	    const { config } = ctx;
296	    const visit = visitTurn(await ctx.services.events(), ctx.node.id);
297	    const harness: HarnessPort | undefined = ctx.ports.harnesses[config.harness];
298	    const { model, effort } = await ctx.services.resolveModel(
299	      config.harness,
300	      visit.freshSession?.model ?? config.model,
301	      visit.freshSession?.effort ?? config.effort,
302	    );
303	    const workingDirectory = await ctx.services.workingDirectory();
304	
305	    // Input transforms shape only the view the prompt sees; they are not persisted.
306	    const viewThread: ContextThread = config.input.length
307	      ? (await runMutations(ctx, ctx.thread, config.input)).thread
308	      : ctx.thread;
309	    const view = threadView(viewThread) as unknown as Record<string, unknown>;
310	
311	    for (const file of config.contextFiles ?? []) {
312	      await ctx.ports.workspace.writeFile(
313	        workingDirectory,
314	        file.path,
315	        await renderTemplate(file.template, view),
316	      );
317	    }
318	
319	    // Provenance comes from this run's open logical visit, never a session repository row.
320	    const missingFailure = (task?: PendingTurn): RunFailureError => {
321	      const origin: MissingSession['origin'] =
322	        (!task || (task.turn.promptKind === 'authored' && task.turn.resumeSessionId)) &&
323	        config.session.policy !== 'fresh'
324	          ? config.session.policy
325	          : 'current-visit';
326	      const sessionId = task?.sessionId ?? task?.turn.resumeSessionId;
327	      const missingSession: MissingSession = {
328	        visitId: visit.visitId,
329	        harness: config.harness,
330	        origin,
331	        model,
332	        effort,
333	        ...(sessionId ? { sessionId } : {}),
334	      };
335	      return new RunFailureError(
336	        'HARNESS_SESSION_MISSING',
337	        `The ${config.harness} session ${sessionId ? `"${sessionId}"` : '(no recorded handle)'} from ${origin} is missing. Choose Start fresh session for node "${ctx.node.id}" to continue without its prior provider conversation.`,
338	        {
339	          nodeId: ctx.node.id,
340	          resumable: false,
341	          missingSession,
342	          ...(task ? { inference: provenance(task) } : {}),
343	        },
344	      );
345	    };
346	    let pending = visit.pending;
347	    let resumeId: string | undefined;
348	    let prompt: string;
349	    let promptKind: PendingTurn['turn']['promptKind'] = 'authored';
350	    if (pending) {
351	      if (pending.submission === 'session-missing') throw missingFailure(pending);
352	      if (pending.submission === 'delivery-uncertain' && !canContinueTurn(pending))
353	        throw recoveryFailure(pending, ctx.node.id);
354	      if (pending.submission === 'definitely-not-submitted') {
355	        prompt = pending.turn.prompt;
356	        promptKind = pending.turn.promptKind;
357	        resumeId = pending.turn.resumeSessionId;
358	      } else {
359	        resumeId = pending.sessionId;
360	        prompt = CONTINUATION_PROMPT;
361	        promptKind = 'continuation';
362	      }
363	    } else {
364	      prompt = visit.freshSession?.prompt ?? (await renderTemplate(config.prompt.template, view));
365	      if (visit.freshSession) {
366	        // This explicit choice applies only to this logical visit; the authored policy stays.
367	        resumeId = undefined;
368	      } else if (config.session.policy === 'resume-previous') {
369	        resumeId = (await ctx.ports.sessions.latestWithSession(ctx.run.id, config.harness))
370	          ?.sessionId;
371	      } else if (config.session.policy === 'resume-named') {
372	        resumeId = (
373	          await ctx.ports.sessions.byScopeKey(
374	            `${ctx.thread.run.loopId}:${config.session.key}`,
375	            config.harness,
376	          )
377	        )?.sessionId;
378	      } else if (config.session.policy === 'resume-own' && visit.completedVisits > 0) {
