403	        const window = await harness.contextWindow(
404	          {
405	            workingDirectory,
406	            model,
407	            effort,
408	            options: config.harnessOptions,
409	            ...(config.capabilities ? { capabilities: config.capabilities } : {}),
410	            turn: {
411	              prompt,
412	              ...(config.output.schema?.native
413	                ? { outputSchema: config.output.schema.jsonSchema }
414	                : {}),
415	            },
416	          },
417	          timeout.signal,
418	        );
