442	        throw mapHarnessFailure(error, undefined, ctx.node.id, config.harness).failure;
443	      }
444	    }
445	    const beginTurn = (
446	      text: string,
447	      kind: PendingTurn['turn']['promptKind'],
448	      id?: string,
449	    ): PendingTurn => {
450	      const turn = {
451	        visitId: visit.visitId,
452	        turnId: ctx.services.newId(),
453	        harness: config.harness,
454	        prompt: text,
455	        promptKind: kind,
456	        ...(admittedContext
457	          ? {
458	              context:
459	                kind === 'authored'
460	                  ? admittedContext
461	                  : { ...admittedContext, retainedHistoryPairs: 0, omittedHistoryPairs: 0 },
462	            }
463	          : {}),
464	        ...(id ? { resumeSessionId: id } : {}),
