473	    const recordTurn = (task: PendingTurn) =>
474	      ctx.services.record({ type: 'harness.turn', nodeId: ctx.node.id, ...task.turn });
475	    // A safe retry retains the original turn identity and exact rendered prompt.
476	    if (!pending || pending.submission !== 'definitely-not-submitted') {
477	      pending = beginTurn(prompt, promptKind, resumeId);
478	      // A crash after this append may occur on either side of invocation: uncertain by default.
479	    } else {
480	      // Re-record the same task intent before another invocation. This resets any init-only ID
481	      // from the refused invocation, so a fresh retry cannot recover into that unused session.
482	      pending = {
483	        turn: pending.turn,
484	        submission: 'delivery-uncertain',
485	        accepted: false,
486	        ...(resumeId ? { sessionId: resumeId } : {}),
487	      };
488	    }
489	
490	    const row: HarnessSessionRecord = {
491	      runId: ctx.run.id,
492	      nodeId: ctx.node.id,
493	      attempt: ctx.attempt,
494	      harness: config.harness,
495	      status: 'starting',
496	      model,
497	      effort,
498	      updatedAt: ctx.services.now(),
499	      ...(resumeId ? { sessionId: resumeId } : {}),
500	      ...(config.session.policy === 'resume-named'
501	        ? { scopeKey: `${ctx.thread.run.loopId}:${config.session.key}` }
