507	      ...(schema?.native ? { outputSchema: schema.jsonSchema } : {}),
508	    };
509	    const sessionRequest = (next: HarnessTurnRequest): HarnessStartRequest => ({
510	      workingDirectory,
511	      model,
512	      effort,
513	      options: config.harnessOptions,
514	      ...(config.capabilities ? { capabilities: config.capabilities } : {}),
