518	    let result: HarnessResult;
519	    let session: HarnessSession | undefined;
520	    let invoking = false;
521	    let intentUnconfirmed = true;
522	    pending.intentUnconfirmed = true;
523	    const failures: TurnFailures = { rejected: false, recording: [] };
