1	import type { PatchOperation } from '@graphgoblin/contracts';
2	import { JsonPatchSchema, SCRIPT_PROGRESS_STDERR_MAX } from '@graphgoblin/contracts';
3	import { assertMutablePatch, threadView, type MutationError } from '@graphgoblin/domain';
4	import { RunCancelledError, RunFailureError } from '../errors.js';
5	import type { NodeHandler } from '../handler.js';
6	import { jsonOrText, outputPatch, withTimeout } from './common.js';
7	import { renderTemplate } from '@graphgoblin/domain';
8	import { scriptVisit, SCRIPT_UNCERTAIN_MESSAGE } from './script-dispatch.js';
9	
10	const SECRET_PREFIX = 'secret:';
11	
12	export const scriptHandler: NodeHandler<'script'> = {
13	  kind: 'script',
14	  async execute(ctx) {
15	    // Check before preparation: a missing workspace/secret must not hide a previous effect.
16	    const visitId = scriptVisit(await ctx.services.events(), ctx.run.id, ctx.node.id);
17	    const { config } = ctx;
18	    const view = threadView(ctx.thread) as unknown as Record<string, unknown>;
19	    const cwd = config.cwd === 'workspace' ? await ctx.services.workingDirectory() : config.cwd;
20	
21	    const env: Record<string, string> = {};
22	    for (const [key, value] of Object.entries(config.env ?? {})) {
23	      if (value.startsWith(SECRET_PREFIX)) {
24	        const name = value.slice(SECRET_PREFIX.length);
25	        const resolved = await ctx.ports.secrets.resolve(name);
26	        if (resolved === undefined) {
27	          throw new RunFailureError(
28	            'SECRET_MISSING',
29	            `secret "${name}" referenced by env ${key} is not configured`,
30	            { nodeId: ctx.node.id },
31	          );
32	        }
33	        env[key] = resolved;
34	      } else {
35	        env[key] = value;
36	      }
37	    }
38	
39	    const args: string[] = [];
40	    for (const arg of config.args) args.push(await renderTemplate(arg, view));
41	
42	    const stdin =
43	      config.stdin === 'thread'
44	        ? JSON.stringify(ctx.thread)
45	        : config.stdin === 'last-output'
46	          ? JSON.stringify(ctx.thread.lastOutput?.value ?? null)
47	          : undefined;
48	
49	    if (ctx.signal.aborted) throw new RunCancelledError();
50	    const dispatchId = ctx.services.newId();
51	    await ctx.services.record({
52	      type: 'script.dispatched',
53	      nodeId: ctx.node.id,
54	      visitId,
55	      dispatchId,
56	    });
57	    const timeout = withTimeout(
58	      ctx.signal,
59	      config.timeoutSeconds,
60	      () => new Error('script timeout'),
61	    );
62	    let result;
63	    try {
64	      result = await ctx.ports.scripts.run({
65	        command: config.command,
66	        args,
67	        cwd,
68	        env,
69	        ...(stdin !== undefined ? { stdin } : {}),
70	        ...(config.timeoutSeconds !== undefined ? { timeoutMs: config.timeoutSeconds * 1000 } : {}),
71	        signal: timeout.signal,
72	      });
73	    } catch {
74	      // An unclassified runner rejection cannot prove the command never executed.
75	      throw new RunFailureError('SCRIPT_OUTCOME_UNCERTAIN', SCRIPT_UNCERTAIN_MESSAGE, {
76	        nodeId: ctx.node.id,
77	        script: { visitId, dispatchId, state: 'outcome-uncertain' },
78	      });
79	    } finally {
80	      timeout.dispose();
81	    }
82	    if (result.terminationUnconfirmed) {
83	      throw new RunFailureError(
84	        'SCRIPT_TERMINATION_UNCONFIRMED',
85	        'Script process tree termination was not confirmed; stop the process before restarting',
86	        {
87	          nodeId: ctx.node.id,
88	          resumable: false,
89	          script: { visitId, dispatchId, state: 'outcome-uncertain' },
90	          details: {
91	            interruptedByStop:
92	              timeout.signal.reason instanceof RunFailureError &&
93	              timeout.signal.reason.code === 'RUN_INTERRUPTED_BY_STOP',
94	          },
95	        },
96	      );
97	    }
98	    if (ctx.signal.aborted) throw new RunCancelledError();
99	    const script = {
100	      visitId,
101	      dispatchId,
102	      state: result.state,
103	      ...(result.exitCode !== null ? { exitCode: result.exitCode } : {}),
104	    };
105	    if (result.state !== 'completed') {
106	      throw new RunFailureError(
107	        result.state === 'definitely-not-started'
108	          ? 'SCRIPT_START_FAILED'
109	          : 'SCRIPT_OUTCOME_UNCERTAIN',
110	        result.state === 'definitely-not-started'
111	          ? 'The script process could not start. Resume tries to start it again.'
112	          : SCRIPT_UNCERTAIN_MESSAGE,
113	        { nodeId: ctx.node.id, script },
114	      );
115	    }
116	    if (result.timedOut || timeout.timedOut()) {
117	      throw new RunFailureError(
118	        'SCRIPT_TIMEOUT',
119	        `script exceeded ${config.timeoutSeconds ?? 0}s`,
120	        { nodeId: ctx.node.id, script },
121	      );
122	    }
123	
124	    const exitCode = result.exitCode ?? -1;
125	    const route = config.exitCodeRoutes?.[String(exitCode)] ?? (exitCode === 0 ? 'out' : undefined);
126	    await ctx.services.record({
127	      type: 'node.progress',
128	      nodeId: ctx.node.id,
129	      progress: {
130	        exitCode,
131	        stderr: result.stderr.slice(-SCRIPT_PROGRESS_STDERR_MAX),
132	        stdoutBytes: result.stdoutBytes,
133	      },
134	    });
135	    if (!route) {
136	      throw new RunFailureError('SCRIPT_EXIT_CODE', `script exited with code ${exitCode}`, {
137	        nodeId: ctx.node.id,
138	        script,
139	        details: {
140	          exitCode,
141	          stderr: result.stderr.slice(-4000),
142	          stdout: result.stdout.slice(-4000),
143	        },
144	      });
145	    }
146	
147	    let patch: PatchOperation[] = [];
148	    if (config.stdout === 'patch') {
149	      let parsed: unknown;
150	      try {
151	        parsed = JSON.parse(result.stdout);
152	      } catch (error) {
153	        throw new RunFailureError(
154	          'SCRIPT_EXIT_CODE',
155	          `script stdout is not a JSON patch: ${error instanceof Error ? error.message : String(error)}`,
156	          { nodeId: ctx.node.id, script },
157	        );
158	      }
159	      const checked = JsonPatchSchema.safeParse(parsed);
160	      if (!checked.success) {
161	        throw new RunFailureError(
162	          'SCRIPT_EXIT_CODE',
163	          `script stdout is not a valid JSON patch: ${checked.error.issues.map((i) => i.message).join('; ')}`,
