26	  addUsage,
27	  makeMessage,
28	  messagePatch,
29	  outputPatch,
30	  selectCollection,
31	  selectMessages,
32	  toJson,
33	} from './common.js';
34	
35	type Seed = Pick<
36	  Partial<ContextThread>,
37	  'messages' | 'vars' | 'artifacts' | 'outputs' | 'lastOutput'
38	>;
39	
40	async function buildSeed(ctx: NodeContext<'subloop'>): Promise<Seed> {
41	  const { input } = ctx.config;
42	  const thread = ctx.thread;
43	  const view = threadView(thread) as unknown as Record<string, unknown>;
44	  const seed: Seed = {};
45	
46	  if (input.mode === 'inherit') {
47	    const excluded = new Set(input.exclude ?? []);
48	    if (!excluded.has('messages')) seed.messages = [...thread.messages];
49	    if (!excluded.has('vars')) seed.vars = { ...thread.vars };
50	    if (!excluded.has('artifacts')) seed.artifacts = [...thread.artifacts];
51	    if (!excluded.has('outputs')) seed.outputs = { ...thread.outputs };
52	    if (!excluded.has('lastOutput') && thread.lastOutput) seed.lastOutput = thread.lastOutput;
53	  } else if (input.mode === 'project') {
54	    seed.messages = await selectMessages(thread.messages, input.messages ?? 'none', view);
55	    seed.artifacts = await selectCollection(thread.artifacts, input.artifacts ?? 'none', view);
56	  }
57	
58	  if (input.vars) {
59	    const vars: Record<string, JsonValue> = { ...(seed.vars ?? {}) };
60	    for (const [name, expression] of Object.entries(input.vars)) {
61	      vars[name] = toJson(await evaluateExpression(expression, view));
62	    }
63	    seed.vars = vars;
64	  }
65	
66	  if (input.inject?.length) {
67	    const injected: Message[] = [];
68	    for (const message of input.inject) {
69	      injected.push(
70	        makeMessage(ctx, message.role, await ctx.services.render(message.content), message.tags),
71	      );
72	    }
73	    seed.messages = [...(seed.messages ?? []), ...injected];
74	  }
75	  return seed;
76	}
77	
78	async function outputMapping(
79	  ctx: NodeContext<'subloop'>,
80	  child: ChildOutcome,
81	): Promise<PatchOperation[]> {
82	  const { output } = ctx.config;
83	  const parent = ctx.thread;
84	  const parentView = threadView(parent) as unknown as Record<string, unknown>;
85	  const childView = child.thread
86	    ? (threadView(child.thread) as unknown as Record<string, unknown>)
87	    : undefined;
88	  // A child that returned no output passes none: `result` stays absent, never `null` (docs/03).
89	  const result = child.result !== undefined ? { result: child.result } : {};
90	  const summary = toJson({
91	    status: child.status,
92	    outcome: child.outcome ?? null,
93	    ...result,
94	    childRunId: child.runId,
95	  });
96	  const patch: PatchOperation[] = [];
97	
98	  if (output.mode === 'custom') {
99	    const value = await evaluateExpression(output.custom?.patch ?? '[]', {
100	      parent: parentView,
101	      child: childView ?? null,
102	      ...result,
103	      outcome: child.outcome ?? null,
104	      status: child.status,
105	    });
106	    const checked = JsonPatchSchema.safeParse(value);
107	    if (!checked.success) {
108	      throw new RunFailureError(
109	        'EXPRESSION_ERROR',
110	        `custom output mapping did not produce a JSON patch: ${checked.error.issues.map((i) => i.message).join('; ')}`,
111	        { nodeId: ctx.node.id },
112	      );
113	    }
114	    try {
115	      assertMutablePatch(checked.data);
116	    } catch (error) {
117	      throw new RunFailureError(
118	        'EXPRESSION_ERROR',
119	        `custom output mapping is outside the mutable regions: ${(error as MutationError).message}`,
120	        { nodeId: ctx.node.id },
121	      );
122	    }
123	    patch.push(...checked.data);
124	    return patch;
125	  }
126	
127	  if (output.resultTo.lastOutput)
128	    patch.push(...outputPatch(parent, ctx.node.id, summary, ctx.services.now()));
129	
130	  // Variables are merged into one replacement so the merge strategy and the result variable compose.
131	  let vars: Record<string, JsonValue> = { ...parent.vars };
132	  let varsChanged = false;
133	
134	  if (output.mode === 'merge' && child.thread) {
135	    const childThread = child.thread;
136	    if (output.vars) {
137	      if (output.vars.strategy === 'explicit') {
138	        for (const [name, expression] of Object.entries(output.vars.map ?? {})) {
139	          vars[name] = toJson(await evaluateExpression(expression, childView));
140	        }
141	      } else if (output.vars.strategy === 'parent-wins') {
142	        vars = { ...childThread.vars, ...vars };
143	      } else {
144	        vars = { ...vars, ...childThread.vars };
145	      }
146	      varsChanged = true;
147	    }
148	    const messages = await selectMessages(
149	      childThread.messages,
150	      output.messages ?? 'none',
151	      childView ?? {},
152	    );
153	    for (const message of messages) patch.push(messagePatch(message));
154	    const artifacts = await selectCollection(
155	      childThread.artifacts,
156	      output.artifacts ?? 'none',
157	      childView ?? {},
158	    );
159	    for (const artifact of artifacts)
160	      patch.push({ op: 'add', path: '/artifacts/-', value: toJson(artifact) });
161	  }
162	  // The result variable is applied after any merge, so it holds exactly what the child returned:
163	  // a merged variable of the same name (the child's inherited copy, say) never overrides it.
164	  const resultVar = output.resultTo.var;
165	  if (resultVar && child.result !== undefined) {
166	    vars[resultVar] = child.result;
167	    varsChanged = true;
168	  } else if (resultVar && Object.hasOwn(vars, resultVar)) {
169	    // No output: the variable no longer holds a result (an earlier visit's, or a merged copy).
170	    vars = Object.fromEntries(Object.entries(vars).filter(([name]) => name !== resultVar));
171	    varsChanged = true;
172	  }
173	  if (varsChanged) patch.push({ op: 'replace', path: '/vars', value: toJson(vars) });
174	
175	  if (output.usage === 'roll-up' && child.thread) {
176	    patch.push({
177	      op: 'replace',
178	      path: '/counters/usage',
179	      value: toJson(addUsage(parent.counters.usage, child.thread.counters.usage)),
180	    });
181	  }
182	  return patch;
183	}
