185	export const subloopHandler: NodeHandler<'subloop'> = {
186	  kind: 'subloop',
187	  async execute(ctx) {
188	    const { config } = ctx;
189	    // The child this visit awaits: the child of its recorded park (woken or not), or the one this
190	    // visit's `child_run.started` names (the process died before the park was recorded), so a
191	    // second one is never started (docs/05, crash recovery).
192	    const awaited = ctx.previousWait?.childRunId ?? (await childOfThisVisit(ctx));
193	    if (awaited) {
194	      let child = await ctx.services.childOutcome(awaited);
195	      // This run failed with its child's resumable failure and was explicitly resumed: resume the
196	      // child in place, as resuming an inline failure re-executes the failed node (#251).
197	      if (child.failure?.resumable && failedSinceAwaiting(await ctx.services.events(), ctx.node.id))
198	        child = await ctx.services.resumeChild(awaited);
199	      // The parent continues only after its child has finished: an unfinished child (one resumed
200	      // after it notified, say) is awaited again rather than mapped.
201	      if (!isTerminal(child.status)) {
202	        return {
203	          kind: 'park',
204	          patch: [],
205	          wait: { nodeId: ctx.node.id, kind: 'child', childRunId: awaited },
206	        };
207	      }
208	      return finishWithChild(ctx, child);
209	    }
210	    const depth = await ctx.services.depth();
211	    const limit = config.depthLimitOverride ?? ctx.definition.settings.subloopDepthLimit;
212	    if (depth + 1 > limit) {
213	      throw new RunFailureError(
214	        'SUBLOOP_DEPTH_EXCEEDED',
215	        `subloop depth ${depth + 1} exceeds the limit ${limit}`,
216	        { nodeId: ctx.node.id, resumable: false },
217	      );
218	    }
219	    const seed = await buildSeed(ctx);
220	    const view = threadView(ctx.thread) as unknown as Record<string, unknown>;
221	    const triggerPayload = config.input.trigger
222	      ? toJson(await evaluateExpression(config.input.trigger.payload, view))
223	      : ctx.thread.invocation.trigger.payload;
224	    // The child and this visit's `child_run.started` are one commit (#320): a crash leaves both or
225	    // neither, so recovery finds this child above or starts the only one.
226	    const childRunId = await ctx.services.startChild({
227	      nodeId: ctx.node.id,
228	      loopId: config.loopRef.loopId,
229	      version: config.loopRef.version,
230	      seed,
231	      triggerPayload,
232	      depthLimit: limit,
233	    });
234	    return { kind: 'park', patch: [], wait: { nodeId: ctx.node.id, kind: 'child', childRunId } };
235	  },
236	};
237	
238	async function finishWithChild(
239	  ctx: NodeContext<'subloop'>,
240	  child: ChildOutcome,
241	): Promise<NodeResult> {
242	  const events = await ctx.services.events();
243	  // A wake durably names the observed child outcome before it can be consumed. A child retried
244	  // independently while this parent was interrupted needs a fresh park/wake for its new outcome.
245	  if (
246	    child.terminalSeq === undefined ||
247	    lastChildWakeSeq(events, child.runId) !== child.terminalSeq
248	  )
249	    return {
250	      kind: 'park',
251	      patch: [],
252	      wait: { nodeId: ctx.node.id, kind: 'child', childRunId: child.runId },
253	    };
254	  // The child's completion is written in the same append as this visit's own outcome: its
255	  // `node.finished`, its `run.failed` or its cancellation (#398). A process that dies first leaves
256	  // neither, so the re-executed visit records the completion exactly once, and a visit that never
257	  // durably reached an outcome never claims to have observed one.
258	  const completion: EventDraft = {
259	    type: 'child_run.finished',
260	    nodeId: ctx.node.id,
261	    childRunId: child.runId,
262	    status: child.status,
263	    ...(child.outcome ? { outcome: child.outcome } : {}),
264	  };
265	  const records = finishRecorded(events, child.runId, child.terminalSeq) ? [] : [completion];
266	  // Ordinary failure rules (#251): the child's execution error or cancellation is the parent's,
267	  // exactly as if the failing work had run inline. An authored outcome (Success, Failure or
268	  // Exhausted exit) is data for the output mapping.
269	  if (child.status === 'cancelled') throw new ChildCancelledError(child.runId, records);
270	  if (child.failure) {
271	    const { code, resumable, nodeId, script } = child.failure;
272	    const { message, details, diagnostics } = childFailureForPublication(child.failure);
273	    if (diagnostics.length) {
274	      ctx.ports.logger.error(
275	        {
276	          runId: ctx.run.id,
277	          nodeId: ctx.node.id,
278	          childRunId: child.runId,
279	          childNodeId: nodeId,
280	          diagnostics,
281	        },
282	        'subloop child failure contained internal diagnostics',
283	      );
284	    }
285	    const summary = `subloop child ${child.runId} failed: ${message}`;
286	    const options: RunFailureError['options'] = {
287	      nodeId: ctx.node.id,
288	      resumable,
289	      ...(script ? { script } : {}),
290	      details: {
291	        childRunId: child.runId,
292	        ...(nodeId ? { childNodeId: nodeId } : {}),
293	        ...(details !== undefined ? { childDetails: details } : {}),
294	      },
295	      records,
296	    };
297	    throw code === 'INTERNAL_ERROR'
298	      ? new InternalRunFailureError(summary, options)
299	      : new RunFailureError(code, summary, options);
300	  }
301	  let patch: NodeResult['patch'];
302	  try {
303	    patch = await outputMapping(ctx, child);
304	  } catch (error) {
305	    // The completion stands even when this run cannot map it; keep it with the failure, classified
306	    // exactly as the executor classifies an error a handler lets escape.
307	    if (error instanceof RunFailureError)
308	      throw new RunFailureError(error.code, error.message, {
309	        ...error.options,
310	        records: [...records, ...(error.options.records ?? [])],
311	      });
312	    ctx.ports.logger.error(
313	      {
314	        runId: ctx.run.id,
315	        nodeId: ctx.node.id,
316	        childRunId: child.runId,
317	        error: errorDiagnostic(error),
318	      },
319	      'subloop output mapping failed',
320	    );
321	    throw new InternalRunFailureError(INTERNAL_FAILURE_MESSAGE, {
322	      nodeId: ctx.node.id,
323	      records,
324	    });
325	  }
326	  return { kind: 'done', patch, route: 'out', records };
327	}
328	
329	/**
330	 * Whether this run failed after it parked on (or started) this node's child: it is executing
331	 * again, so it was explicitly resumed from that failure.
332	 */
333	function failedSinceAwaiting(events: readonly RunEvent[], nodeId: string): boolean {
334	  for (let i = events.length - 1; i >= 0; i -= 1) {
335	    const event = events[i] as RunEvent;
336	    if (event.type === 'run.failed') return true;
337	    if (
338	      (event.type === 'run.waiting' || event.type === 'child_run.started') &&
339	      event.nodeId === nodeId
340	    )
341	      return false;
342	  }
343	  return false;
344	}
345	
346	/** Outcome identity carried by an identity-bound child wake; the payload is ordinary JSON. */
347	function childWakeSeq(event: RunEvent, childRunId: string): number | undefined {
348	  if (event.type !== 'run.woken' || event.reason !== 'child') return undefined;
349	  const payload = event.payload;
350	  if (
351	    !payload ||
352	    typeof payload !== 'object' ||
353	    Array.isArray(payload) ||
354	    payload.childRunId !== childRunId
355	  )
356	    return undefined;
357	  return typeof payload.childFinishedSeq === 'number' ? payload.childFinishedSeq : undefined;
358	}
359	
360	function lastChildWakeSeq(events: readonly RunEvent[], childRunId: string): number | undefined {
361	  for (let index = events.length - 1; index >= 0; index -= 1) {
362	    const seq = childWakeSeq(events[index] as RunEvent, childRunId);
363	    if (seq !== undefined) return seq;
364	  }
365	  return undefined;
366	}
367	
368	/** A finish belongs to the durable child-outcome identity observed by its preceding child wake. */
369	function finishRecorded(
370	  events: readonly RunEvent[],
371	  childRunId: string,
372	  terminalSeq: number,
373	): boolean {
374	  let observed: number | undefined;
375	  for (const event of events) {
376	    const seq = childWakeSeq(event, childRunId);
377	    if (seq !== undefined) observed = seq;
378	    if (
379	      event.type === 'child_run.finished' &&
380	      event.childRunId === childRunId &&
381	      observed === terminalSeq
382	    )
383	      return true;
384	  }
385	  return false;
386	}
387	
388	/** The child this node started during its current, unfinished visit, from the run's log. */
389	async function childOfThisVisit(ctx: NodeContext<'subloop'>): Promise<string | undefined> {
390	  const events = await ctx.services.events();
391	  for (let i = events.length - 1; i >= 0; i -= 1) {
392	    const event = events[i] as RunEvent;
393	    if (event.type === 'node.finished' && event.nodeId === ctx.node.id) return undefined;
394	    if (event.type === 'child_run.started' && event.nodeId === ctx.node.id) return event.childRunId;
395	  }
396	  return undefined;
397	}
