1	import { and, eq, lt, sql } from 'drizzle-orm';
2	import { dirname, sep } from 'node:path';
3	import { setImmediate as yieldTurn } from 'node:timers/promises';
4	import { directoryKey, physicalDirectory } from '../fs/physical-path.js';
5	import type { Database, SqliteTransaction } from './db.js';
6	import { workspaceReferences, workspaceReferenceState } from './schema.js';
7	
8	/** Resolution is done before the transaction that records a use or definition. */
9	export async function recordWorkspacePhysical(
10	  tx: SqliteTransaction,
11	  id: string,
12	  path: string,
13	  physical: string | null,
14	): Promise<void> {
15	  await tx
16	    .update(workspaceReferences)
17	    .set({
18	      physicalPath: physical,
19	      checkedEpoch: sql`(SELECT epoch FROM workspace_reference_state WHERE id = 1)`,
20	    })
21	    .where(and(eq(workspaceReferences.id, id), eq(workspaceReferences.path, path)));
22	}
23	
24	/** One bounded, restartable refresh sweep. No filesystem call holds the SQLite statement lock. */
25	export class SqliteWorkspaceReferences {
26	  private started = false;
27	  constructor(private readonly db: Database) {}
28	
29	  async refreshBatch(signal?: AbortSignal): Promise<void> {
30	    const [state] = await this.db.select().from(workspaceReferenceState);
31	    // A restart never trusts an old, partly completed filesystem observation.
32	    if (!this.started || !state!.sweeping) {
33	      await this.db.update(workspaceReferenceState).set({ epoch: sql`epoch + 1`, sweeping: true });
34	      this.started = true;
35	    }
36	    const [current] = await this.db.select().from(workspaceReferenceState);
37	    const epoch = current!.epoch;
38	    const rows = await this.db
39	      .select()
40	      .from(workspaceReferences)
41	      .where(lt(workspaceReferences.checkedEpoch, epoch))
42	      .orderBy(workspaceReferences.checkedEpoch, workspaceReferences.id)
43	      .limit(2048);
44	    const resolved = new Map<string, string | null>();
45	    // One bounded indexed update per 32 observations avoids a durable commit per path.
46	    for (let offset = 0; offset < rows.length; offset += 32) {
47	      const observed: {
48	        id: string;
49	        path: string | null;
50	        priorEpoch: number;
51	        physical: string | null;
52	      }[] = [];
53	      for (const row of rows.slice(offset, offset + 32)) {
54	        if (signal?.aborted) return;
55	        // Pending paths are literal Liquid templates; WorkspacePort trims their rendered value.
56	        // An empty literal can only fail resolution, so it has no possible future workspace use.
57	        const path = row.id.startsWith('pending:') ? row.path?.trim() : row.path;
58	        if (row.id.startsWith('pending:') && row.path !== null && path === '') {
59	          await this.db
60	            .delete(workspaceReferences)
61	            .where(
62	              and(
63	                eq(workspaceReferences.id, row.id),
64	                eq(workspaceReferences.path, row.path),
65	                eq(workspaceReferences.checkedEpoch, row.checkedEpoch),
66	              ),
67	            );
68	          continue;
69	        }
70	        let physical: string | null = null;
71	        if (path !== null && path !== undefined) {
72	          if (!resolved.has(path)) resolved.set(path, await physicalDirectory(path));
73	          physical = resolved.get(path)!;
74	        }
75	        observed.push({ id: row.id, path: row.path, priorEpoch: row.checkedEpoch, physical });
76	      }
77	      if (signal?.aborted) return;
78	      if (!observed.length) continue;
79	      await this.db.run(sql`WITH observed(id, path, prior_epoch, physical) AS (VALUES
80	        ${sql.join(
81	          observed.map((row) => sql`(${row.id}, ${row.path}, ${row.priorEpoch}, ${row.physical})`),
82	          sql`, `,
83	        )})
84	        UPDATE workspace_references AS current SET physical_path = observed.physical, checked_epoch = ${epoch}
85	        FROM observed WHERE current.id = observed.id AND current.path IS observed.path
86	          AND current.checked_epoch = observed.prior_epoch`);
87	      await yieldTurn();
88	    }
89	    const [older] = await this.db
90	      .select({ id: workspaceReferences.id })
91	      .from(workspaceReferences)
92	      .where(lt(workspaceReferences.checkedEpoch, epoch))
93	      .limit(1);
94	    if (!older) await this.db.update(workspaceReferenceState).set({ sweeping: false });
95	  }
96	}
97	
98	/** Indexed null, ancestor equality and descendant range probes; no history-size scan or I/O. */
99	export async function workspaceReferenced(
100	  tx: Database | SqliteTransaction,
101	  physical: string | null | undefined,
102	): Promise<boolean> {
103	  if (!physical) return true;
104	  const [sweep] = await tx.all(
105	    sql`SELECT 1 FROM workspace_reference_state WHERE id = 1 AND sweeping = 1`,
106	  );
107	  if (sweep) return true;
108	  const [unknown] = await tx.all(
109	    sql`SELECT 1 FROM workspace_references WHERE physical_path IS NULL LIMIT 1`,
110	  );
111	  if (unknown) return true;
112	  const ancestors = [physical];
113	  let parent = dirname(physical.slice(0, -1));
114	  while (!ancestors.includes(directoryKey(parent))) {
115	    ancestors.push(directoryKey(parent));
116	    parent = dirname(parent);
117	  }
118	  const [enclosing] = await tx.all(sql`SELECT 1 FROM workspace_references
119	    WHERE physical_path IN (${sql.join(
120	      ancestors.map((path) => sql`${path}`),
121	      sql`, `,
122	    )}) LIMIT 1`);
123	  if (enclosing) return true;
124	  const upper = physical.slice(0, -1) + String.fromCharCode(sep.charCodeAt(0) + 1);
125	  const [enclosed] = await tx.all(sql`SELECT 1 FROM workspace_references
126	    WHERE physical_path >= ${physical} AND physical_path < ${upper} LIMIT 1`);
127	  return Boolean(enclosed);
128	}
