2	import type { HarnessEvent, HarnessPort, HarnessResult } from '../ports.js';
3	import { FakeHarness } from './fakes.js';
4	import { singleNodeLoop } from './scenario.js';
5	
6	/** Public-port fixtures shared by the handler and HTTP provenance boundary matrices. */
7	export const failureCases = [
8	  { code: 'HARNESS_TERMINATION_UNCONFIRMED', state: 'delivery-uncertain', eligible: false },
9	  { code: 'HARNESS_SESSION_MISSING', state: 'session-missing', eligible: false },
10	  { code: 'HARNESS_ARGUMENTS_REJECTED', state: 'definitely-not-submitted', eligible: false },
11	  { code: 'HARNESS_INVALID_CONFIGURATION', state: 'definitely-not-submitted', eligible: false },
12	  { code: 'HARNESS_UNSUPPORTED_POLICY', state: 'definitely-not-submitted', eligible: false },
13	  { code: 'HARNESS_TRANSPORT_FAILED', state: 'definitely-not-submitted', eligible: true },
14	  { code: 'HARNESS_NOT_AUTHENTICATED', state: 'definitely-not-submitted', eligible: true },
15	  { code: 'HARNESS_QUOTA_EXHAUSTED', state: 'delivery-uncertain', eligible: true },
16	  { code: 'HARNESS_TIMEOUT', state: 'delivery-uncertain', eligible: true },
17	  { code: 'HARNESS_NOT_INSTALLED', state: 'definitely-not-submitted', eligible: true },
18	  { code: 'HARNESS_TRANSPORT_FAILED', state: 'delivery-uncertain', eligible: true },
19	  { code: 'HARNESS_TURN_FAILED', state: 'delivery-uncertain', eligible: true },
20	] as const;
21	export type FailureCase = (typeof failureCases)[number];
22	export const failureSources = [
23	  'launch',
24	  'event',
25	  'iterator',
26	  'result',
27	  'cleanup',
28	  'cancel',
29	] as const;
30	export type FailureSource = (typeof failureSources)[number];
31	export const recordingModes = ['ok', 'before', 'after'] as const;
32	
33	export function failureLoop(family: HarnessId) {
34	  return singleNodeLoop('Failure evidence matrix', {
35	    id: 'infer',
