/** Project an admitted paused Resume; the caller holds the run lock (also during startup). */
private async completePausedResume(runId: string): Promise<RunRecord | undefined> {
  const events = await this.ports.events.read(runId);
  if (!pendingResume(events)) return undefined;
  const parked = parkedWait(events);
  const updated = await this.ports.runs.transition(
    runId,
    ['paused'],
    {
      status: parked ? 'waiting' : 'running',
      pausedAt: undefined,
      ...(parked
        ? { waiting: parked.wait, currentNodeId: parked.wait.nodeId }
        : { failure: undefined, finishedAt: undefined }),
    },
    { observedSeq: events.at(-1)?.seq ?? 0 },
  );
  if (!updated) return undefined;
  // No timer or child reconciliation is exposed before both the intent and status exist.
  if (parked) {
    await this.rearmTimers(runId, parked.wait);
    await this.reconcileChild(updated);
  } else this.enqueue(runId);
  return this.mustGet(runId);
}

/** Explicitly abandon only the failed node's missing provider conversation (#265). */
async recoverSession(
  runId: string,
  nodeId: string,
  failureSeq: number,
  actor: Actor = SYSTEM_ACTOR,
): Promise<RunRecord> {
  return this.withWork(async () => {
    this.assertAdmissionOpen();
    return this.withRunLock(runId, async () => {
      const run = await this.mustGet(runId);
      const events = await this.ports.events.read(runId);
      const failed = terminalEvent(events);
      const missing = run.failure?.missingSession;
      const version = await this.ports.loops.getVersion(run.versionId);
      const node = version && nodeById(version.definition, nodeId);
      const visit = visitTurn(events, nodeId);
      if (
        run.status !== 'failed' ||
        run.failure?.code !== 'HARNESS_SESSION_MISSING' ||
        run.failure.nodeId !== nodeId ||
        run.currentNodeId !== nodeId ||
        failed?.type !== 'run.failed' ||
        failed.seq !== failureSeq ||
        !missing ||
        missing.visitId !== visit.visitId ||
        node?.kind !== 'inference' ||
        node.config.harness !== missing.harness
      )
        throw new EngineRequestError(
          'INVALID_STATE',
          'The observed missing-session failure is no longer current for this inference node',
        );
      const authored = events.find(
        (event) =>
          event.type === 'harness.turn' &&
          event.nodeId === nodeId &&
          event.visitId === visit.visitId &&
          event.promptKind === 'authored',
      );
      await this.ports.runs.clearFinalized(runId);
      // The choice, actor/time and resume intent commit in one event. Startup already completes
      // durable resumes; no transient flag or session-row rewrite can lose this decision.
      await this.ports.events.append(runId, [
        {
          type: 'run.resumed',
          actor,
          freshSession: {
            ...missing,
            nodeId,
            failureSeq,
            priorContextCarried: false,
            ...(authored?.type === 'harness.turn' ? { prompt: authored.prompt } : {}),
          },
        },
      ]);
      const resumed = await this.completeResume(runId);
      if (!resumed)
        throw new EngineRequestError('INVALID_STATE', 'The run changed during session recovery');
      return resumed;
    });
  });
}

/** Move a failed run whose resume is durable back to running and queue it. */
private async completeResume(runId: string): Promise<RunRecord | undefined> {
  const updated = await this.ports.runs.transition(runId, ['failed'], {
    status: 'running',
    pausedAt: undefined,
    failure: undefined,
    finishedAt: undefined,
  });
  if (updated) this.enqueue(runId);
  return updated;
}

async provideInput(
  runId: string,
  waitId: string,
  payload: JsonValue,
  actor: Actor = SYSTEM_ACTOR,
): Promise<RunRecord> {
  return this.withWork(() => this.provideRunInput(runId, waitId, payload, actor));
}

private async provideRunInput(
  runId: string,
  waitId: string,
  payload: JsonValue,
  actor: Actor = SYSTEM_ACTOR,
): Promise<RunRecord> {
  if (this.forcing) this.assertAdmissionOpen();
  const run = await this.mustGet(runId);
  if (run.status === 'paused' && run.waiting?.waitId === waitId) {
    throw new EngineRequestError(
      'INVALID_STATE',
      'The run is paused; resume it before providing input',
    );
  }
  if (
    run.status !== 'waiting' ||
    run.waiting?.kind !== 'input' ||
    run.waiting.waitId !== waitId
  ) {
    throw new EngineRequestError('WAIT_MISMATCH', 'The observed input wait is no longer active');
  }
  if (run.waiting.inputSchema) {
    const validation = validateJson(run.waiting.inputSchema, payload);
    if (!validation.ok) {
      throw new EngineRequestError(
        'INVALID_INPUT',
        'input is invalid: ' + validation.errors.join('; '),
        { errors: validation.errors },
      );
    }
  }
  void actor;
  return this.wake(runId, { reason: 'input', payload }, waitId);
}

/** Record a signal only against the park the sender observed. */
async signal(
  runId: string,
  name: string,
  waitId: string,
  payload: JsonValue = null,
): Promise<{ run: RunRecord; woke: boolean }> {
  return this.withWork(() => this.signalRun(runId, name, waitId, payload));
}

private async signalRun(
  runId: string,
  name: string,
  waitId: string,
  payload: JsonValue = null,
): Promise<{ run: RunRecord; woke: boolean }> {
  // Match wake's bounded ten conflict retries; a saturated caller must refresh its snapshot.
  for (let attempt = 0; attempt < 10; attempt += 1) {
    if (this.forcing) this.assertAdmissionOpen();
    const run = await this.mustGet(runId);
    if (run.status === 'paused' && run.waiting?.waitId === waitId) {
      throw new EngineRequestError(
        'INVALID_STATE',
        'The run is paused; resume it before sending a signal',
      );
    }
    if (
      run.status !== 'waiting' ||
      !run.waiting ||
      run.waiting.waitId !== waitId ||
      run.cancelRequestedAt
    ) {
      throw new EngineRequestError(
        'WAIT_MISMATCH',
        'The observed signal wait is no longer active',
      );
    }
    const events = await this.ports.events.read(runId, run.waiting.startedSeq - 1);
    if (parkedWait(events)?.wait.waitId !== waitId) {
      // A retry must also complete an earlier durable signal answer's lost status write.
      // wake repairs that acknowledgement, then rejects without appending this signal.
      if (findPendingWake(events)) await this.wake(runId, { reason: 'signal', payload }, waitId);
      throw new EngineRequestError(
        'WAIT_MISMATCH',
        'The observed signal wait is already answered',
      );
    }
    let wakes = run.waiting.kind === 'signal' && run.waiting.signalName === name;
    if (wakes) {
      const version = await this.ports.loops.getVersion(run.versionId);
      const node = version ? nodeById(version.definition, run.waiting.nodeId) : undefined;
      if (node?.kind === 'wait' && node.config.mode === 'signal' && node.config.filter) {
        const thread = await this.getThread(runId);
        wakes = await evaluatePredicate(node.config.filter, payload, {
          bindings: { thread: thread ? threadView(thread) : {} },
        });
      }
    }
    const received: EventDraft = { type: 'signal.received', name, payload };
    if (wakes) {
      return {
        run: await this.wake(runId, { reason: 'signal', payload }, waitId, [received]),
        woke: true,
      };
    }
    try {
      await this.ports.events.append(runId, [received], {
        expectedLastSeq: events.at(-1)?.seq ?? 0,
      });
      return { run, woke: false };
    } catch (error) {
      if (!(error instanceof AppendConflictError)) throw error;
    }

